using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public class EvaluationTests
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [AssemblyInitialize]
    public static void Initialize(TestContext context)
    {
        s_reportingConfiguration = CreateReportingConfiguration();
    }

    [AssemblyCleanup]
    public static async Task Cleanup()
    {
        if (s_reportingConfiguration is not null)
        {
            await s_reportingConfiguration.DisposeAsync();
        }
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var path = Path.Combine(
            Path.GetDirectoryName(typeof(EvaluationTests).Assembly.Location)!,
            "evaluation-report");

        var reportStore = new DiskBasedReportingConfiguration(storageRootPath: path);

        return reportStore;
    }

    [TestMethod]
    public async Task ChatRespondsRelevantly()
    {
        await using var appHost = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        await using var app = await appHost.BuildAsync();
        await app.StartAsync();

        var chatClient = app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        var responseText = response.Text ?? string.Empty;

        Assert.IsFalse(
            string.IsNullOrWhiteSpace(responseText),
            "Chat response should not be empty.");

        var evaluators = new IEvaluator[]
        {
            new RelevanceTruthAndCompletenessEvaluator()
        };

        var chatConfiguration = new ChatConfiguration(chatClient);

        await using var scenario = await s_reportingConfiguration!
            .CreateScenarioRunAsync(
                scenarioName: nameof(ChatRespondsRelevantly),
                evaluators: evaluators);

        var evalMessages = messages.Concat([new ChatMessage(ChatRole.Assistant, responseText)]).ToList();
        await scenario.EvaluateAsync(evalMessages, chatConfiguration);
    }
}

